records.command:
$productionProcesses=Get-CimInstance Win32_Process
$productionPids=@{}; foreach($productionProcess in $productionProcesses){$productionPids[[int]$productionProcess.ProcessId]=$true}
$productionProcesses | Where-Object { $_.CommandLine -like '*production-frozen*semantic-worker.py*' -or $_.CommandLine -like '*production-frozen*production-mcp.mjs*' } | ForEach-Object { [PSCustomObject]@{Name=$_.Name;Pid=$_.ProcessId;ParentPid=$_.ParentProcessId;ParentAlive=$productionPids.ContainsKey([int]$_.ParentProcessId);WorkingSetBytes=$_.WorkingSetSize} } | ConvertTo-Json -Compress
